CREATE TABLE IF NOT EXISTS `CauHinhHeThong` (`maCauHinh` varchar(36) NOT NULL, `khoa` varchar(100) NOT NULL, `giaTri` json NOT NULL, `moTa` varchar(500) NULL, `ngayCapNhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `nguoiCapNhatId` varchar(36) NOT NULL, PRIMARY KEY (`maCauHinh`), UNIQUE KEY `uq_CauHinhHeThong_khoa` (`khoa`), CONSTRAINT `fk_CauHinhHeThong_nguoiCapNhatId` FOREIGN KEY (`nguoiCapNhatId`) REFERENCES `TaiKhoan` (`maTaiKhoan`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `DanhMucSuCo` (`maDanhMuc` varchar(36) NOT NULL, `ma` varchar(50) NOT NULL, `ten` varchar(100) NOT NULL, `dangHoatDong` boolean NOT NULL DEFAULT true, `thuTu` integer NOT NULL DEFAULT 0, PRIMARY KEY (`maDanhMuc`), UNIQUE KEY `uq_DanhMucSuCo_ma` (`ma`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
